package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.GET("/search", func(c *gin.Context) {
		// 参数存在就返回它的值，不存在返回空串
		q := c.Query("q")
		// 只有参数没传时才用默认值；传了空串照样返回空串
		page := c.DefaultQuery("page", "1")
		size := c.DefaultQuery("size", "20")
		// 同名参数出现多次时拿到全部
		tags := c.QueryArray("tag")
		// 参数不存在时拿到的是 nil
		missing := c.QueryArray("missing")
		// 想区分「没传」和「传了空串」用 GetQuery
		raw, ok := c.GetQuery("q")
		c.JSON(http.StatusOK, gin.H{
			"q":       q,
			"page":    page,
			"size":    size,
			"tags":    tags,
			"missing": missing,
			"raw":     raw,
			"exists":  ok,
		})
	})

	// page 传了但是空串，size 根本没传
	req := httptest.NewRequest(http.MethodGet, "/search?q=go&page=&tag=web&tag=api", nil)
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println(w.Code, w.Body.String())
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strconv"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.GET("/users/:id/posts/:postID", func(c *gin.Context) {
		// 路径参数的名字就是路由里冒号后面那一段
		id := c.Param("id")
		postID := c.Param("postID")
		// 路由里没声明的参数取不到，返回空串
		missing := c.Param("nope")
		// 路径参数一律是字符串，要自己转
		n, err := strconv.Atoi(id)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "id 必须是数字"})
			return
		}
		c.JSON(http.StatusOK, gin.H{"id": n, "post_id": postID, "missing": missing})
	})

	req := httptest.NewRequest(http.MethodGet, "/users/42/posts/7", nil)
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println(w.Code, w.Body.String())
}

