func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.POST("/login", func(c *gin.Context) {
		// 只认 POST 的表单体：urlencoded 或 multipart
		name := c.PostForm("name")
		// 没传才用默认值
		role := c.DefaultPostForm("role", "guest")
		// 同名参数出现多次时拿到全部
		tags := c.PostFormArray("tag")
		// query 参数在这里取不到
		fromQuery := c.Query("from")
		c.JSON(http.StatusOK, gin.H{
			"name":      name,
			"role":      role,
			"tags":      tags,
			"fromQuery": fromQuery,
		})
	})

	body := "name=tom&role=admin&tag=a&tag=b"
	req := httptest.NewRequest(http.MethodPost, "/login?from=query", strings.NewReader(body))
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println(w.Code, w.Body.String())
}

