import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

// 一个结构体上写好几个 tag，每个绑定器只看自己那一个
type Payload struct {
	Name string `json:"name" xml:"name" yaml:"name" uri:"name" form:"name"`
	Age  int    `json:"age" xml:"age" yaml:"age" uri:"age" form:"age"`
}

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()

	// 请求体按 JSON 解
	r.POST("/json", func(c *gin.Context) {
		var p Payload
		if err := c.ShouldBindJSON(&p); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, p)
	})

	// 只取 URL 上的查询参数
	r.GET("/query", func(c *gin.Context) {
		var p Payload
		if err := c.ShouldBindQuery(&p); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, p)
	})

	// 只取路由里的路径参数
	r.GET("/uri/:name", func(c *gin.Context) {
		var p Payload
		if err := c.ShouldBindUri(&p); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, p)
	})

	// 请求体按 XML 解
	r.POST("/xml", func(c *gin.Context) {
		var p Payload
		if err := c.ShouldBindXML(&p); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, p)
	})

	// 请求体按 YAML 解
	r.POST("/yaml", func(c *gin.Context) {
		var p Payload
		if err := c.ShouldBindYAML(&p); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, p)
	})

	cases := []struct {
		method      string
		path        string
		body        string
		contentType string
	}{
		{http.MethodPost, "/json", `{"name":"tom","age":18}`, "application/json"},
		{http.MethodGet, "/query?name=tom&age=18", "", ""},
		{http.MethodGet, "/uri/tom", "", ""},
		{http.MethodPost, "/xml", `<Payload><name>tom</name><age>18</age></Payload>`, "application/xml"},
		{http.MethodPost, "/yaml", "name: tom\nage: 18\n", "application/yaml"},
	}
	for _, tc := range cases {
		req := httptest.NewRequest(tc.method, tc.path, strings.NewReader(tc.body))
		if tc.contentType != "" {
			req.Header.Set("Content-Type", tc.contentType)
		}
		w := httptest.NewRecorder()
		r.ServeHTTP(w, req)
		fmt.Printf("%s -> %d %s\n", tc.path, w.Code, w.Body.String())
	}
}

