import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

// 四个 tag 各管各的
type User struct {
	Name string `form:"name" json:"name" uri:"name" binding:"required"`
	Age  int    `form:"age" json:"age" uri:"age" binding:"gte=0"`
}

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()

	// 表单绑定：看 form tag
	r.POST("/form", func(c *gin.Context) {
		var u User
		if err := c.ShouldBind(&u); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, u)
	})

	// JSON 绑定：看 json tag
	r.POST("/json", func(c *gin.Context) {
		var u User
		if err := c.ShouldBindJSON(&u); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, u)
	})

	// 路径绑定：看 uri tag
	r.GET("/uri/:name", func(c *gin.Context) {
		var u User
		if err := c.ShouldBindUri(&u); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, u)
	})

	// 查询参数绑定：也看 form tag
	r.GET("/query", func(c *gin.Context) {
		var u User
		if err := c.ShouldBindQuery(&u); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, u)
	})

	// 表单：form tag 生效
	req := httptest.NewRequest(http.MethodPost, "/form", strings.NewReader("name=tom&age=18"))
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println("/form ->", w.Code, w.Body.String())

	// JSON：json tag 生效，缺 name 被 binding tag 拦下
	req2 := httptest.NewRequest(http.MethodPost, "/json", strings.NewReader(`{"age":18}`))
	req2.Header.Set("Content-Type", "application/json")
	w2 := httptest.NewRecorder()
	r.ServeHTTP(w2, req2)
	fmt.Println("/json ->", w2.Code, w2.Body.String())

	// 路径参数：uri tag 生效
	req3 := httptest.NewRequest(http.MethodGet, "/uri/tom", nil)
	w3 := httptest.NewRecorder()
	r.ServeHTTP(w3, req3)
	fmt.Println("/uri ->", w3.Code, w3.Body.String())

	// 查询参数：binding tag 照样校验，缺 required 的 name 就报错
	req4 := httptest.NewRequest(http.MethodGet, "/query?age=18", nil)
	w4 := httptest.NewRecorder()
	r.ServeHTTP(w4, req4)
	fmt.Println("/query ->", w4.Code, w4.Body.String())
}

