import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

type User struct {
	Name string `json:"name" binding:"required"`
	Age  int    `json:"age" binding:"gte=18"`
}

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()

	// 校验不过：400
	r.POST("/strict", func(c *gin.Context) {
		var u User
		if err := c.ShouldBindJSON(&u); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, u)
	})

	// 格式对但内容不合法：422 也是常见选择
	r.POST("/semantic", func(c *gin.Context) {
		var u User
		if err := c.ShouldBindJSON(&u); err != nil {
			c.JSON(http.StatusUnprocessableEntity, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, u)
	})

	// Content-Type 不对：415
	r.POST("/json-only", func(c *gin.Context) {
		if c.ContentType() != "application/json" {
			c.JSON(http.StatusUnsupportedMediaType, gin.H{"error": "只收 application/json"})
			return
		}
		var u User
		if err := c.ShouldBindJSON(&u); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, u)
	})

	// body 不是合法 JSON：400
	req := httptest.NewRequest(http.MethodPost, "/strict", strings.NewReader(`{"name":`))
	req.Header.Set("Content-Type", "application/json")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println("/strict ->", w.Code, w.Body.String())

	// 校验不过：422
	body := `{"name":"tom","age":10}`
	req2 := httptest.NewRequest(http.MethodPost, "/semantic", strings.NewReader(body))
	req2.Header.Set("Content-Type", "application/json")
	w2 := httptest.NewRecorder()
	r.ServeHTTP(w2, req2)
	fmt.Println("/semantic ->", w2.Code, w2.Body.String())

	// Content-Type 不对：415
	req3 := httptest.NewRequest(http.MethodPost, "/json-only", strings.NewReader(body))
	req3.Header.Set("Content-Type", "text/plain")
	w3 := httptest.NewRecorder()
	r.ServeHTTP(w3, req3)
	fmt.Println("/json-only ->", w3.Code, w3.Body.String())
}

