import (
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
	"github.com/go-playground/validator/v10"
)

type User struct {
	Name  string `json:"name" binding:"required,min=2"`
	Age   int    `json:"age" binding:"gte=18"`
	Email string `json:"email" binding:"required,email"`
}

// 一条结构化的错误
type FieldError struct {
	Field   string `json:"field"`
	Rule    string `json:"rule"`
	Param   string `json:"param,omitempty"`
	Message string `json:"message"`
}

// 把绑定错误转成结构化的列表
func toFieldErrors(err error) []FieldError {
	var ve validator.ValidationErrors
	if !errors.As(err, &ve) {
		// 不是校验错误，是 JSON 语法错误或者类型不匹配
		return []FieldError{{Field: "_", Rule: "parse", Message: err.Error()}}
	}
	out := make([]FieldError, 0, len(ve))
	for _, fe := range ve {
		out = append(out, FieldError{
			Field:   fe.Field(),
			Rule:    fe.Tag(),
			Param:   fe.Param(),
			Message: fmt.Sprintf("%s 不满足 %s 规则", fe.Field(), fe.Tag()),
		})
	}
	return out
}

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.POST("/users", func(c *gin.Context) {
		var u User
		if err := c.ShouldBindJSON(&u); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"errors": toFieldErrors(err)})
			return
		}
		c.JSON(http.StatusOK, u)
	})

	body := `{"name":"t","age":10,"email":"bad"}`
	req := httptest.NewRequest(http.MethodPost, "/users", strings.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println(w.Code, w.Body.String())
}

