type User struct {
	Name string `json:"name" binding:"required"`
	Age  int    `json:"age"`
}

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()

	// 绑到结构体：字段固定，类型固定，还能校验
	r.POST("/struct", func(c *gin.Context) {
