package main

import (
	"bytes"
	"fmt"
	"mime/multipart"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.POST("/upload", func(c *gin.Context) {
		// 取上传的文件，没有这个字段时返回 http.ErrMissingFile
		fh, err := c.FormFile("file")
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		// 文件名、大小这些元信息都在 FileHeader 里
		info := gin.H{"filename": fh.Filename, "size": fh.Size}

		// 直接落盘，SaveUploadedFile 会自己建目录
		dir, err := os.MkdirTemp("", "upload")
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
			return
		}
		defer os.RemoveAll(dir)
		dst := filepath.Join(dir, fh.Filename)
		if err := c.SaveUploadedFile(fh, dst); err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
			return
		}
		data, err := os.ReadFile(dst)
		if err != nil {
			c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
			return
		}
		info["content"] = string(data)
		c.JSON(http.StatusOK, info)
	})

	// 造一个 multipart 请求
	var buf bytes.Buffer
	w := multipart.NewWriter(&buf)
	fw, err := w.CreateFormFile("file", "hello.txt")
	if err != nil {
		panic(err)
	}
	if _, err := fw.Write([]byte("hello gin")); err != nil {
		panic(err)
	}
	_ = w.WriteField("desc", "测试文件")
	if err := w.Close(); err != nil {
		panic(err)
	}

	req := httptest.NewRequest(http.MethodPost, "/upload", &buf)
	req.Header.Set("Content-Type", w.FormDataContentType())
	rec := httptest.NewRecorder()
	r.ServeHTTP(rec, req)
	fmt.Println(rec.Code, rec.Body.String())
}

package main

import (
	"errors"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"

	"github.com/gin-gonic/gin"
)

type User struct {
	Name string `json:"name" binding:"required"`
}

func main() {
	gin.SetMode(gin.TestMode)
	r := gin.New()
	r.POST("/users", func(c *gin.Context) {
		// 把请求体限制在 1KB，超了读取时直接报错
		c.Request.Body = http.MaxBytesReader(c.Writer, c.Request.Body, 1024)
		var u User
		if err := c.ShouldBindJSON(&u); err != nil {
			// 超限是 413，其余的解析、校验错误是 400
			var maxErr *http.MaxBytesError
			if errors.As(err, &maxErr) {
				c.JSON(http.StatusRequestEntityTooLarge, gin.H{"error": "请求体太大", "limit": maxErr.Limit})
				return
			}
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, u)
	})

	// 超限
	big := `{"name":"` + strings.Repeat("a", 2048) + `"}`
	req := httptest.NewRequest(http.MethodPost, "/users", strings.NewReader(big))
	req.Header.Set("Content-Type", "application/json")
	w := httptest.NewRecorder()
	r.ServeHTTP(w, req)
	fmt.Println("超限 ->", w.Code, w.Body.String())

	// 正常
	req2 := httptest.NewRequest(http.MethodPost, "/users", strings.NewReader(`{"name":"tom"}`))
	req2.Header.Set("Content-Type", "application/json")
	w2 := httptest.NewRecorder()
	r.ServeHTTP(w2, req2)
	fmt.Println("正常 ->", w2.Code, w2.Body.String())
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"

	"github.com/gin-gonic/gin"
)

func main() {
	gin.SetMode(gin.TestMode)

	// 默认配置：信任所有代理，X-Forwarded-For 说了算
	defaultEngine := gin.New()
	defaultEngine.GET("/ip", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{
			"client_ip": c.ClientIP(),
			"remote_ip": c.RemoteIP(),
		})
	})

	// 只信任内网代理，别的请求一律看 TCP 对端地址
	strictEngine := gin.New()
	if err := strictEngine.SetTrustedProxies([]string{"10.0.0.0/8"}); err != nil {
		panic(err)
	}
	strictEngine.GET("/ip", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{
			"client_ip": c.ClientIP(),
			"remote_ip": c.RemoteIP(),
		})
	})

	req := httptest.NewRequest(http.MethodGet, "/ip", nil)
	req.Header.Set("X-Forwarded-For", "203.0.113.9")
	w := httptest.NewRecorder()
	defaultEngine.ServeHTTP(w, req)
	fmt.Println("默认 ->", w.Code, w.Body.String())

	req2 := httptest.NewRequest(http.MethodGet, "/ip", nil)
	req2.Header.Set("X-Forwarded-For", "203.0.113.9")
	w2 := httptest.NewRecorder()
	strictEngine.ServeHTTP(w2, req2)
	fmt.Println("收紧 ->", w2.Code, w2.Body.String())
}
